<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Bouncing Ball Physics Playground</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    padding: 20px;
  }
  h1 {
    font-size: 1.4rem;
    font-weight: 600;
    margin-bottom: 16px;
    color: #a0c4ff;
    text-shadow: 0 0 20px rgba(160,196,255,0.3);
    letter-spacing: 0.5px;
  }
  .controls {
    display: flex;
    gap: 10px;
    margin-bottom: 16px;
  }
  button {
    background: #16213e;
    color: #e0e0e0;
    border: 1px solid #0f3460;
    padding: 8px 20px;
    border-radius: 8px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: all 0.2s ease;
    user-select: none;
  }
  button:hover {
    background: #0f3460;
    border-color: #a0c4ff;
    box-shadow: 0 0 12px rgba(160,196,255,0.2);
  }
  button:active {
    transform: scale(0.96);
  }
  button.active {
    background: #1a5276;
    border-color: #5dade2;
    box-shadow: 0 0 15px rgba(93,173,226,0.3);
  }
  #sim {
    border: 2px solid #0f3460;
    border-radius: 12px;
    background: #0d1117;
    box-shadow: 0 0 40px rgba(0,0,0,0.5), inset 0 0 60px rgba(0,0,0,0.3);
    cursor: crosshair;
  }
  .info {
    margin-top: 12px;
    font-size: 0.8rem;
    color: #667;
    text-align: center;
  }
</style>
</head>
<body>
  <h1>⚽ Bouncing Ball Physics</h1>
  <div class="controls">
    <button id="drop">Drop Ball</button>
    <button id="play">Play</button>
    <button id="clear">Clear</button>
  </div>
  <canvas id="sim" width="600" height="600"></canvas>
  <div class="info">Click on the canvas to add balls</div>

<script>
(function() {
  const canvas = document.getElementById('sim');
  const ctx = canvas.getContext('2d');
  const W = canvas.width;
  const H = canvas.height;

  const GRAVITY = 600;        // pixels/s²
  const RESTITUTION = 0.72;   // energy kept on bounce
  const DEFAULT_RADIUS = 16;
  const AIR_FRICTION = 0.999; // very slight damping

  let balls = [];
  let playing = false;
  let animId = null;
  let lastTime = null;

  // Nice color palette for balls
  const COLORS = [
    '#ff6b6b', '#ffa502', '#ffd93d', '#6bff6b',
    '#45aaf2', '#a55eea', '#fd79a8', '#00cec9',
    '#e17055', '#74b9ff', '#55efc4', '#ffeaa7'
  ];

  function randomColor() {
    return COLORS[Math.floor(Math.random() * COLORS.length)];
  }

  function createBall(x, y, vx, vy, r) {
    return {
      x: x !== undefined ? x : W / 2 + (Math.random() - 0.5) * 200,
      y: y !== undefined ? y : 40,
      vx: vx || 0,
      vy: vy || 0,
      r: r || (DEFAULT_RADIUS + Math.random() * 10 - 5),
      color: randomColor()
    };
  }

  function clamp(val, min, max) {
    return Math.max(min, Math.min(max, val));
  }

  function drawBall(ball) {
    const { x, y, r, color } = ball;

    // Glow
    ctx.save();
    ctx.shadowColor = color;
    ctx.shadowBlur = 15;

    // Main circle
    const grad = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
    grad.addColorStop(0, '#ffffff');
    grad.addColorStop(0.3, color);
    grad.addColorStop(1, shadeColor(color, -40));

    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
    ctx.restore();

    // Highlight
    ctx.beginPath();
    ctx.arc(x - r * 0.25, y - r * 0.25, r * 0.35, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.25)';
    ctx.fill();
  }

  function shadeColor(hex, percent) {
    let num = parseInt(hex.replace('#', ''), 16);
    let r = Math.min(255, Math.max(0, (num >> 16) + percent));
    let g = Math.min(255, Math.max(0, ((num >> 8) & 0x00FF) + percent));
    let b = Math.min(255, Math.max(0, (num & 0x0000FF) + percent));
    return '#' + (0x1000000 + r * 0x10000 + g * 0x100 + b).toString(16).slice(1);
  }

  function draw() {
    ctx.clearRect(0, 0, W, H);

    // Subtle grid
    ctx.strokeStyle = 'rgba(255,255,255,0.03)';
    ctx.lineWidth = 1;
    for (let i = 0; i < W; i += 40) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.stroke();
    }
    for (let j = 0; j < H; j += 40) {
      ctx.beginPath(); ctx.moveTo(0, j); ctx.lineTo(W, j); ctx.stroke();
    }

    // Floor highlight
    ctx.strokeStyle = 'rgba(160,196,255,0.15)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, H - 1);
    ctx.lineTo(W, H - 1);
    ctx.stroke();

    for (let i = 0; i < balls.length; i++) {
      drawBall(balls[i]);
    }
  }

  function physicsStep(dt) {
    // dt in seconds
    for (let i = 0; i < balls.length; i++) {
      const b = balls[i];

      // Apply gravity
      b.vy += GRAVITY * dt;

      // Air friction
      b.vx *= Math.pow(AIR_FRICTION, dt * 60);
      b.vy *= Math.pow(AIR_FRICTION, dt * 60);

      // Update position
      b.x += b.vx * dt;
      b.y += b.vy * dt;

      // Bounce off left wall
      if (b.x - b.r < 0) {
        b.x = b.r;
        b.vx = -b.vx * RESTITUTION;
      }
      // Bounce off right wall
      if (b.x + b.r > W) {
        b.x = W - b.r;
        b.vx = -b.vx * RESTITUTION;
      }
      // Bounce off top
      if (b.y - b.r < 0) {
        b.y = b.r;
        b.vy = -b.vy * RESTITUTION;
      }
      // Bounce off bottom
      if (b.y + b.r > H) {
        b.y = H - b.r;
        b.vy = -b.vy * RESTITUTION;
      }
    }
  }

  function step(dt) {
    dt = dt !== undefined ? dt : 1;
    // If dt is dimensionless (default 1), treat as 1/60 second tick
    // to keep physics at a reasonable rate
    if (dt === 1) {
      dt = 1 / 60;
    }
    physicsStep(dt);
    draw();
  }

  function animationLoop(timestamp) {
    if (!playing) return;

    if (lastTime === null) lastTime = timestamp;
    let dt = (timestamp - lastTime) / 1000;
    lastTime = timestamp;

    // Cap dt to prevent huge jumps
    if (dt > 0.1) dt = 0.016;

    // Sub-step for stability
    const subSteps = 3;
    const subDt = dt / subSteps;
    for (let s = 0; s < subSteps; s++) {
      physicsStep(subDt);
    }
    draw();

    animId = requestAnimationFrame(animationLoop);
  }

  function startPlaying() {
    if (playing) return;
    playing = true;
    lastTime = null;
    document.getElementById('play').textContent = 'Pause';
    document.getElementById('play').classList.add('active');
    animId = requestAnimationFrame(animationLoop);
  }

  function stopPlaying() {
    playing = false;
    if (animId) cancelAnimationFrame(animId);
    animId = null;
    document.getElementById('play').textContent = 'Play';
    document.getElementById('play').classList.remove('active');
  }

  function togglePlay() {
    if (playing) {
      stopPlaying();
    } else {
      startPlaying();
    }
  }

  function addBall(x, y, vx, vy, r) {
    vx = vx || 0;
    vy = vy || 0;
    const ball = createBall(x, y, vx, vy, r);
    balls.push(ball);
    draw();
    return ball;
  }

  function clearBalls() {
    balls = [];
    draw();
  }

  function getBalls() {
    // Return copies of ball data
    return balls.map(function(b) {
      return { x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r };
    });
  }

  // Expose API
  window.sim = {
    w: W,
    h: H,
    balls: getBalls,
    addBall: addBall,
    clear: clearBalls,
    step: step
  };

  // Button handlers
  document.getElementById('drop').addEventListener('click', function() {
    const x = W / 2 + (Math.random() - 0.5) * 300;
    const y = 50 + Math.random() * 50;
    addBall(x, y, (Math.random() - 0.5) * 200, Math.random() * 50);
  });

  document.getElementById('play').addEventListener('click', togglePlay);
  document.getElementById('clear').addEventListener('click', function() {
    stopPlaying();
    clearBalls();
  });

  // Click on canvas to add ball
  canvas.addEventListener('click', function(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;
    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;
    addBall(x, y, (Math.random() - 0.5) * 150, -Math.random() * 100 - 50);
  });

  // Initial draw
  draw();
})();
</script>
</body>
</html>
